import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddress, formatValue, colName } from './util.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addrText = m[0]
  const rest = s.slice(addrText.length).replace(/^[ \t]+/, '')
  const a = parseAddress(addrText)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${addrText}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content: rest })
}

const list = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of list) out.push(`${c.key}=${formatValue(sheet.get(c.key))}`)
} else {
  for (const c of list) {
    let names = []
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p) names = p.deps
    }
    out.push(`${c.key}:` + names.map((n) => ' ' + colName(n.col) + n.row).join(''))
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

