{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261021T225213Z/cell-jJFSWq/src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddress, formatValue, colName } from './util.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addrText = m[0]
  const rest = s.slice(addrText.length).replace(/^[ \t]+/, '')
  const a = parseAddress(addrText)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${addrText}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content: rest })
}

const list = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of list) out.push(`${c.key}=${formatValue(sheet.get(c.key))}`)
} else {
  for (const c of list) {
    let names = []
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p) names = p.deps
    }
    out.push(`${c.key}:` + names.map((n) => ' ' + colName(n.col) + n.row).join(''))
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261021T225213Z/cell-jJFSWq/src/util.js","content":"export function colIndex(letters) {
  const a = letters.toUpperCase()
  if (a.length === 1) return a.charCodeAt(0) - 64
  return 26 + (a.charCodeAt(0) - 65) * 26 + (a.charCodeAt(1) - 64)
}

export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}

export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = colIndex(m[1])
  return { col, row, key: colName(col) + row }
}

export function formatValue(v) {
  switch (v.t) {
    case 'n':
      return String(Number(v.v.toPrecision(10)))
    case 's':
      return v.v
    case 'b':
      return v.v ? 'TRUE' : 'FALSE'
    default:
      return v.v
  }
}
