function lex(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(src.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

// Returns { ast, deps } or null when the grammar rejects the body.
// ast is null-flagged with bad=true when a range sits outside a call argument.
export function parseFormula(src) {
  const toks = lex(src)
  if (!toks) return null
  let p = 0
  let bad = false
  const refs = []
  const peekOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const FAIL = {}

  function addRef(word) {
    const a = parseAddress(word)
    if (a) refs.push(a)
    return a
  }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      const r = add()
      l = { type: 'bin', op, l, r }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) {
      p++
      return { type: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw FAIL
    const t = toks[p++]
    if (t.k === 'num') return { type: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!peekOp(')')) throw FAIL
        p++
        return { type: 'paren', e }
      }
      throw FAIL
    }
    const up = t.v.toUpperCase()
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) {
        p++
      } else {
        for (;;) {
          args.push(cmp())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          throw FAIL
        }
      }
      return { type: 'call', name: up, args }
    }
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw FAIL
      const w2 = toks[p++].v
      const a = addRef(t.v)
      const b = addRef(w2)
      return { type: 'range', a, b }
    }
    if (up === 'TRUE') return { type: 'bool', v: true }
    if (up === 'FALSE') return { type: 'bool', v: false }
    return { type: 'ref', a: addRef(t.v) }
  }

  let ast
  try {
    ast = cmp()
    if (p < toks.length) return null
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }

  // ranges are only allowed as direct call arguments
  function check(n, direct) {
    switch (n.type) {
      case 'range': if (!direct) bad = true; break
      case 'bin': check(n.l, false); check(n.r, false); break
      case 'un': case 'paren': check(n.e, false); break
      case 'call': n.args.forEach((x) => check(x, true)); break
    }
  }
  check(ast, false)

  // expand dependencies
  const set = new Map()
  const add1 = (c, r) => set.set(c * 10000 + r, { col: c, row: r })
  const walk = (n) => {
    switch (n.type) {
      case 'ref': if (n.a) add1(n.a.col, n.a.row); break
      case 'range':
        if (n.a && n.b) {
          for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
            for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) add1(c, r)
        } else {
          if (n.a) add1(n.a.col, n.a.row)
          if (n.b) add1(n.b.col, n.b.row)
        }
        break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(ast)
  const deps = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
  return { ast, bad, deps }
}
"}

