{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261021T225213Z/cell-jJFSWq/src/util.js","content":"export function colIndex(letters) {
  const a = letters.toUpperCase()
  if (a.length === 1) return a.charCodeAt(0) - 64
  return 26 + (a.charCodeAt(0) - 65) * 26 + (a.charCodeAt(1) - 64)
}

export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}

export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = colIndex(m[1])
  return { col, row, key: colName(col) + row }
}

export function formatValue(v) {
  switch (v.t) {
    case 'n':
      return String(Number(v.v.toPrecision(10)))
    case 's':
      return v.v
    case 'b':
      return v.v ? 'TRUE' : 'FALSE'
    default:
      return v.v
  }
}
