import { colName } from './util.js'

const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = (v) => (v.t === 'n' ? 0 : v.t === 's' ? 1 : 2)

function cmpStr(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function compare(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 's') return cmpStr(a.v, b.v)
  const x = a.t === 'b' ? +a.v : a.v
  const y = b.t === 'b' ? +b.v : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.busy.has(key)) return err('#CYCLE!')
    const cell = this.cells.get(key)
    if (!cell) return num(0)
    this.busy.add(key)
    const v = this.compute(cell.content)
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }

  compute(content) {
    if (content[0] === '=') {
      const p = parseFormula(content.slice(1))
      if (!p || p.bad) return err('#ERR!')
      return this.ev(p.ast)
    }
    if (content === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { t: 's', v: content }
  }

  cellAt(a) {
    return this.get(colName(a.col) + a.row)
  }

  ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return n.a ? this.cellAt(n.a) : err('#REF!')
      case 'range': return this.expand(n)[0]
      case 'un': {
        const v = toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
  }

  expand(n) {
    if (!n.a || !n.b) return [err('#REF!')]
    const out = []
    for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
      for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++)
        out.push(this.get(colName(c) + r))
    return out
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.t === 'e') return l
    const r = this.ev(n.r)
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      case '^': return finite(Math.pow(a.v, b.v))
    }
  }

