    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (argc < 1) return err('#ERR!')
    const vals = []
    for (const a of n.args) {
      if (a.type === 'range') vals.push(...this.expand(a))
      else vals.push(this.ev(a))
    }
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
